#include <stdio.h>

void tryToChange(int x) {
    x = 999;
    printf("Inside func: x=%d\n", x);
}

int main() {
    int a = 10;

    printf("Before: %d\n", a);
    tryToChange(a);
    printf("After:  %d\n", a);

    return 0;
}

